"""Record this completed dashboard stage without altering solver controls."""
from pathlib import Path
import datetime,json,shutil,os
R=Path(__file__).resolve().parent;B=R.parent
now=datetime.datetime.now().astimezone();tag=now.strftime('%Y%m%d_%H%M%S')
def read(p):
 try:return json.loads(p.read_text(encoding='utf-8-sig'))
 except (ValueError,OSError):return {}
def write(p,v):
 t=p.with_name(p.name+'.'+str(os.getpid())+'.tmp');t.write_text(json.dumps(v,indent=2,ensure_ascii=False),encoding='utf8');os.replace(t,p)
hold=read(R/'campaign_hold.json')
if hold.get('active') is not True or not (R/'local_control/PAUSE').is_file():raise RuntimeError('Unexpected hold change; do not publish paused handover')
snapshot=dict(updated_at=now.isoformat(),status='dashboard_standalone_prepared_CFD_held',own_solver_launched=False,http_pid=read(R/'manual_control_server.lock').get('pid'),manual_mesh_path=True,mesh_preview_ids=['M10','M11','M12'],dashboard_structure=['computer_status_and_controls','mesh_or_wave_analysis','archive_and_comparisons'],force_definition='CL=(Fz-rho_water*(-g_z)*actual_foil_volume)/(0.5*rho_ref*U_ref^2*A_ref)',raw_force_history_preserved=True,force_reference_review=str(R/'force_reference_review.json'),controller_tests=read(R/'local_control_test_review.json').get('test_count'),actual_zero_step_recipe_status=read(R/'local_control_zero_step_review.json').get('status','not_run'),runtime_validation_pending=True,campaign_hold=hold)
text="""CURRENT DASHBOARD / STANDALONE HANDOVER - """+now.isoformat()+"""
OWN C01/WAVES STILL PAUSED at explicit user request pending the other agent's mesh study. Do not launch, release hold or restart completed controllers. Separate mesh GPU study and HF session are untouched.
Local HTTP service PID """+str(snapshot['http_pid'])+""" serves http://127.0.0.1:8771/. This process is only the dashboard, not a solver.
Both authorized dashboard.html/professor_dashboard.html and work copies are now built by build_manual_dashboard_copy.py. Do not re-run old frozen meeting builders.
Layout: technical computer/current-job tile; collapsed manual controls; Mesh assessment / Waves; automatically archived terminal runs and combined report. Idle live area contains no old C01 numbers. Archive pages are read-only; resume combines only hash-verified matching histories.
Mesh & field preview: real file-only M10/M11/M12 cell-edge plots (317277/595285/1154199 cells); historical matched M07-M09 pressure/streamlines labelled with source/time. Missing current fields are explicitly unavailable. Extend via mesh_field_preview_manifest.json; never relabel old figures as a new mesh. The other mesh agent's live bridge is preserved.
Standalone manual workflow: paste prepared .sim path -> CPU1 zero-flow inspection -> select immutable imported copy -> configure domain/wave -> save queue -> explicit release hold and Start. No implicit old-M10 fallback. New domain/mesh/settings gets separate C01. Computed .sim links, save/pause, verified continuation, result selection and rescue guide are prepared.
New CL convention: subtract nominal fully submerged buoyancy from vertical force before normalization. Raw Fz/CL_total CSVs unchanged. force_reference.py requires actual CGNS displaced volume and native rho/gravity/reference evidence. Current M10 correction22.7176857875N /3855.6N =0.00589212724026CL. Six legacy M10 cases bound individually. Historical M09 source-chain mismatch is recorded; no guessed corrected M09 value. Historical accepted mesh decisions retain their raw basis.
Future C01 stopping and wave cycle tests use correctedCL; raw historical evaluator calls remain explicitly labelled. New PrepareLocalMeshCalm.java audits actual physics before any flow and is compiled; actual zero-step recipe/runtime check remains pending, not claimed passed.
Checks: controller68/68, force reference27/27, cycle evaluator24/24, lifecycle33/33, four actualCGNS buoyancy audits. See final UI review for widths1920/1360/390 and print. No CFD ran in this dashboard stage.
Guide: B/standalone_control_guide.html. Rescue: B/chat_rescue.html and R/CHAT_CONTINUE_LATEST.txt, regenerated by build_standalone_handover.py.
Earlier snapshots below remain archival and cannot override the current user hold.
"""
for name in ['RESUME_AT_HOME.txt','RATUNKOWY_KONTYNUACJA_CHAT.txt']:
 p=R/name
 if p.exists():shutil.copy2(p,R/(p.stem+'_before_dashboard_'+tag+p.suffix));old=p.read_text(encoding='utf-8-sig')
 else:old=''
 p.write_text(text+'\n'+old,encoding='utf8')
for name in ['mesh_selection_plan.json','overnight_plan_20261029.json','wave_numerical_review_current.json']:
 p=R/name
 if not p.exists():continue
 shutil.copy2(p,R/(p.stem+'_before_dashboard_'+tag+'.json'))
 d=read(p);d['current_user_hold']=hold;d['dashboard_standalone_current']=snapshot;d['updated_at']=now.isoformat();write(p,d)
write(R/'dashboard_standalone_stage_20261030.json',snapshot)
print(json.dumps({'status':snapshot['status'],'http_pid':snapshot['http_pid'],'controller_tests':snapshot['controller_tests']}))
